#!/usr/bin/env python3
"""Rebuilds docs/reviews/TESTLOG_H2.md from every result file in h2/res (one row per run or run set), after the hand-written
desk/S0 rows. A row is written for each json; MC grab files are one row per set. usage: make_testlog.py"""
import os, json, glob, re
H=os.path.dirname(os.path.abspath(__file__)); P=os.path.join(H,'..','..','..','..'); OUT=os.path.join(P,'docs','reviews','TESTLOG_H2.md')
DES={'H2_':'Rev H2','B2F_':'B2-F (front dock)','B2n_':'B2 as designed (handle side)','B2r_':'B2 handle side, pad re-set (S11r)'}
HEAD='''# TESTLOG H2: register of every run / run set (Rev H2, B2 as designed, B2-F)
Tool: MuJoCo 3.17.0 (sim) unless stated. Hull: OLD = gate hull (cmp/simH.py l.132 / b2/simB2.py block, front taper 170 mm, lip where each model put it);
NEW = corrected hull h2/hull_h2.py (S1). Result files are relative to revG/sim/cg/. Rows after the desk rows are generated by h2/make_testlog.py from
h2/res/*.json (re-run it to refresh). "calibration" rows are not gate results.

| ID | design | hull | settings | result | pass/fail | result file |
|----|--------|------|----------|--------|-----------|-------------|
| R1 | - | - | receiver side: craemer240_side.png, sulods-2/3.png, weber140_side_crop.png, ese_manual.pdf p.8 (desk check) | comb receiver on the FRONT wall on all three makers' drawings; ESE manual: "upper frontal comb receiver", restraint only on the rear surface / wheels, never the rear handle | confirmed | docs/reviews/GATE_H2_vs_B2F.md s.1 |
| R2 | - | - | front-wall taper scaled from the drawings (desk check) | Craemer 34 mm, SULO 37 mm, Weber 42 mm (gate hull 170*D/0.74 = 125-169 mm) | their claim confirmed (~35 mm) | h2/res/hull_check.json |
| S0a | B2 | OLD | rel WEB140 flat full (b2/runB2.py via h2/rerun.py, results to h2/res/s0) | every key identical to stored (verdict PASS) | reproduced | h2/res/s0/B2_rel_WEB140_flat_full.json |
| S0b | Rev H (fx) | OLD | rel WEB140 flat full, REVH_FIX=liftmax,wheelchk | every key identical (PASS) | reproduced | h2/res/s0/H_rel_WEB140_flat_full_fx.json |
| S0c | B2 | OLD | grab ESE240SL seed 202, MC_IDX 0-2 | 3/3 runs identical | reproduced | h2/res/s0/B2_grab_ESE240SL.json |
| S0d | Rev H (fx) | OLD | grab ESE240SL seed 202, MC_IDX 0-2 | 3/3 runs identical | reproduced | h2/res/s0/H_grab_ESE240SL_fx.json |
| S0e | B2 via h2/simB2h.py | OLD (H2_HULL=old) | rel WEB140 flat full | identical to stored B2 (generator check) | reproduced | h2/res/s0/B2o_rel_WEB140_flat_full.json |
| S1 | - | NEW | hull check plots, 5 bins on the scaled family drawing | see hull_check.json | done | h2/fig/hull_*.png |
| S2 | Rev H2 | - | mass/CG vs params.robot_mass() | 91.00 kg, x 0.3022, z 0.4092 (params 91.0 / 0.3022 / 0.4091) | PASS | h2/res/mass_check_H2.json |
| S12 | Rev H2, B2-F | - | structure hand calcs on simulated peak wheel/comb/pad/lift forces (h2/s12_struct.py; ASSUMED geometry marked) | SF < 2: rails (carry H2 1.30 / B2-F 1.19; edge 0.50 / 0.39), mast uprights at peak comb (1.26 / 0.68), H2 6202 rollers (C0 0.72, tube-face contact yields), H2 comb at roll stop 1.22, B2-F foot-bolt pull-through 1.00 and HGR15 rail screws 1.10; castor outriggers >= 3.5 | fixes stated | h2/res/s12_structure.json |
'''
def sid(name,tag):
    if name.startswith('S5_'): return 'S5'
    if name.startswith('S6_') or name.startswith('tyrecal'): return 'S6'
    if name.startswith('S7_') or '_cg60' in tag or '_cg0' in tag: return 'S7'
    if re.search(r'_g[+-]\d\d',tag): return 'S4'
    if tag.startswith('_l'): return 'S10'
    if tag.startswith('_p'): return 'S3p'
    if tag.startswith('_cal'): return 'cal'
    return 'S3'
rows=[]
for f in sorted(glob.glob(os.path.join(H,'res','*.json'))):
    b=os.path.basename(f); pf=next((k for k in DES if b.startswith(k)),None)
    if not pf: continue
    try: d=json.load(open(f))
    except Exception: continue
    rest=b[len(pf):-5]
    if 'runs' in d and 'captured' in d:   # MC grab set
        m=re.match(r'grab_([A-Z0-9]+)(.*)',rest); bn,tag=m.group(1),m.group(2)
        ns=[r['result'] for r in d['runs'] if r['result']!='success']
        res='%d/%d captured, FH %d, knocked %d%s'%(d['captured'],d['n'],d['false_holds'],d['knocked'],(' (non-success: '+', '.join(sorted(set(ns)))+')') if ns else '')
        pss='PASS' if d['captured']>=28*d['n']/30 and d['false_holds']==0 and d['knocked']==0 else 'FAIL'
        sett='G1 grab MC %s n=%d seed %d %s'%(bn,d['n'],d['seed'],tag)
    else:
        tag=''; m=re.search(r'(_dt025|_p[a-z0-9]+|_g[+-]\d\d|_l[a-z0-9]+|_cg60|_cg0|_cal\S*|_r\S*|_t\S*)$',rest)
        name=rest
        if 'S6_' in rest or 'S5_' in rest or 'S7_' in rest or 'tipcalc' in rest or 'tyrecal' in rest:
            env=d.get('env',{}); tag=env.get('IT1_TAG','')
        elif m: tag=m.group(1)
        t=d.get('test','')
        if 'verdict' in d: res='%s; tilt end %s'%(d['verdict'],d.get('bin_tilt_abs_end')); pss=d['verdict']
        elif t=='S5_retention': res='setup %s; grab %s; eng min %s mm; lip peak %s N (%s x W); in channel %s; captured at end %s; min wheel clear %s m'%(d.get('setup','v1'),d['grab'],d.get('eng_min_mm'),d.get('lip_peak_N'),d.get('lip_peak_x_weight'),d.get('inx_all'),d.get('captured_end'),d.get('clear_min')); pss='PASS' if d['ok'] else 'FAIL'
        elif t=='S6_kerb40_full_width': res='reached %s (%.2f m), seated %s, bin-ground %.0f N, pitch %.1f'%(d['reached'],d['dist_m'],d['seated_all'],d['bin_ground'],d['pitch']); pss=('PASS' if d['ok'] else 'FAIL')+(' (model change)' if d.get('tyre','rigid')!='rigid (gate)' else '')
        elif t=='S7_climb12_nose_up': res='castor min %s N, heading dev %s deg, t %s s, creep %s'%(d['castor_min_N'],d['heading_dev_deg'],d['time_s'],d['hold_creep_m']); pss='PASS' if d['ok'] else 'FAIL'
        elif t.startswith('G8_handcalc'): res='min tip %.1f deg; castor lift-off 110 kg %.1f deg'%(d['tipmin'],d['cases'][0]['castor_liftoff_about_drive_axle_deg']); pss='PASS' if d['tipmin']>=20 else 'FAIL'
        elif t=='tyre calibration': res='deflection %s mm at %s N'%(d['deflection_mm'],d['drive_N']); pss='calibration'
        elif t=='climb12': res='t %s s, dist %s, creep %s'%(d['time_s'],d['dist_m'],d['hold_creep_m']); pss='PASS' if d['ok'] else 'FAIL'
        elif t=='step40': res='dist %s m, seated %s'%(d['dist_m'],d['seated_all']); pss='PASS' if d['ok'] else 'FAIL'
        elif t=='estop12': res='stop %s m, slide %s'%(d['stop_dist_m'],d['slide_after_stop_m']); pss='PASS' if d['ok'] else 'FAIL'
        elif t=='towstab': res='swept %s m, roll %s'%(d['swept_diameter_m'],d['roll']); pss='PASS' if d['ok'] else 'FAIL'
        elif t=='static': res='drive %s/%s N, castors %s N'%(d['driveL'],d['driveR'],d['caster_sum']); pss='PASS' if d['ok'] else 'FAIL'
        else: res=json.dumps({k:v for k,v in d.items() if k in ('ok','result')}); pss=str(d.get('ok'))
        sett=rest
    rows.append('| %s | %s | NEW | %s | %s | %s | h2/res/%s |'%(sid(rest,tag) if not ('runs' in d and 'captured' in d) else ('S4' if re.search(r'_g[+-]\d\d',tag) else 'S10' if tag.startswith('_l') else 'S3p' if tag.startswith('_p') else 'S3' if pf in ('H2_','B2F_') else 'S11'),
                DES[pf],sett.replace('|','/'),res.replace('|','/'),pss,b))
open(OUT,'w').write(HEAD+'\n'.join(rows)+'\n'); print(len(rows),'rows ->',OUT)
